            src={USER_AVATAR}
            alt="Profil"
            className="w-10 h-10 rounded-full border border-slate-200 object-cover"
          />
        </div>
      </header>

      {/* Table Container */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        {/* Table Toolbar */}
