const Clients = () => {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');

  // Helper to calculate duration from DD.MM.YYYY format
  const calculateDuration = (startDateStr: string) => {
    const parts = startDateStr.split('.');
    if (parts.length !== 3) return startDateStr;

    const start = new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]));
    const now = new Date();

    // Calculate difference in months
    let months = (now.getFullYear() - start.getFullYear()) * 12;
    months -= start.getMonth();
    months += now.getMonth();

    // Adjust if current day is less than start day
    if (now.getDate() < start.getDate()) {
        months--;
    }

    if (months < 1) {
        const diffTime = Math.abs(now.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
        return `${diffDays} Gün`;
    }

    return `${months} Ay`;
  };

  // Filter and split clients
  const filteredClients = CLIENTS.filter(client => 
    client.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeClients = filteredClients.filter(c => c.status === 'Aktif');
  const passiveClients = filteredClients.filter(c => c.status === 'Pasif');

  const ClientRow = ({ client }: { client: Client }) => (
