            </button>
        </div>
      </td>
    </tr>
  );

  return (
    <div className="p-8 max-w-7xl mx-auto h-screen flex flex-col">
       {/* Header */}
       <header className="flex justify-between items-center mb-8 flex-shrink-0">
        <div>
          <h1 className="text-3xl font-bold text-slate-800">Danışan Listesi</h1>
          <p className="text-slate-500 mt-1">Danışan ilerlemesini yönetin ve izleyin.</p>
        </div>
