                       Pasif Danışanlar
                    </p>
                  </td>
                </tr>
                {passiveClients.map((client) => (
                  <ClientRow key={client.id} client={client} />
                ))}
              </tbody>
            )}
          </table>
        </div>
      </div>
    </div>
  );
