// Reusable Dynamic Line Chart
const DynamicLineChart = ({ dataPoints, color = "#10B981" }: { dataPoints: number[], color?: string }) => {
  const height = 100;
  const width = 300;
  const max = Math.max(...dataPoints, 100);
  const min = Math.min(...dataPoints, 0);

  const points = dataPoints.map((p, i) => {
    const x = (i / (dataPoints.length - 1)) * width;
    const y = height - ((p - min) / (max - min)) * (height * 0.8) - 10; // padding
    return `${x},${y}`;
  }).join(' ');

  return (
    <div className="w-full h-48 relative">
      <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full overflow-visible" preserveAspectRatio="none">
        {/* Grid */}
        <line x1="0" y1="25" x2={width} y2="25" stroke="#f1f5f9" strokeWidth="1" />
        <line x1="0" y1="50" x2={width} y2="50" stroke="#f1f5f9" strokeWidth="1" />
        <line x1="0" y1="75" x2={width} y2="75" stroke="#f1f5f9" strokeWidth="1" />

        {/* Line */}
        <polyline
          fill="none"
          stroke={color}
          strokeWidth="3"
          points={points}
          strokeLinecap="round"
          strokeLinejoin="round"
          className="drop-shadow-sm transition-all duration-500 ease-in-out"
        />

        {/* Gradient Area */}
        <defs>
          <linearGradient id={`gradient-${color}`} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.2" />
            <stop offset="100%" stopColor="#ffffff" stopOpacity="0" />
          </linearGradient>
        </defs>
        <polygon 
          fill={`url(#gradient-${color})`} 
          points={`0,${height} ${points} ${width},${height}`} 
        />
      </svg>
      <div className="flex justify-between text-[10px] text-slate-400 mt-2 font-medium">
        <span>Pzt</span>
        <span>Çar</span>
        <span>Cum</span>
        <span>Paz</span>
      </div>
    </div>
  );
};

