              )}

              {filteredRecipes.map(recipe => (
                <div 
                  key={recipe.id}
                  onClick={() => handleRecipeSelect(recipe)}
                  className={`flex gap-3 p-2 rounded-xl border transition-all cursor-pointer group ${
                    activeCell 
