               </div>

               {/* The Grid */}
               <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden min-w-[900px]">
                  {/* Header Row */}
                  <div className="grid grid-cols-8 divide-x divide-slate-100 border-b border-slate-200 bg-slate-50">
