              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
              <input 
                 type="text" 
                 placeholder="Notlarda ara..." 
                 value={searchQuery}
                 onChange={(e) => setSearchQuery(e.target.value)}
