           {/* Tags / Quick Filters */}
           <div className="flex gap-2 overflow-x-auto pb-4 pt-2 hide-scrollbar">
              {CATEGORIES.map(cat => (
                 <button 
                   key={cat} 
                   onClick={() => setSelectedCategoryFilter(cat)}
                   className={`px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap transition-colors border ${
