                 </button>
              ))}
           </div>
        </div>

        {/* Notes List */}
        <div className="flex-1 overflow-y-auto px-4 pb-4 space-y-3">
           {filteredNotes.length > 0 ? (
             filteredNotes.map(note => (
                <div 
                   key={note.id}
