                      {note.isPinned && <Pin className="w-3.5 h-3.5 text-diet-green fill-diet-green rotate-45" />}
                   </div>
                   <p className="text-xs text-slate-500 line-clamp-2 mb-3 leading-relaxed">
                      {note.content || 'İçerik yok...'}
