                <p className="text-sm font-medium">Not bulunamadı</p>
                <p className="text-xs mt-1">Yeni bir not oluşturarak başlayın.</p>
             </div>
           )}
        </div>
      </aside>

      {/* --- RIGHT SIDE: Editor --- */}
      <main className="flex-1 flex flex-col min-w-0 bg-[#F7F8F8]">
         {selectedNoteId && activeNote ? (
