const Clients = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);

  // Load clients from Supabase on mount
  useEffect(() => {
    const loadClients = async () => {
      try {
        setLoading(true);
        const data = await fetchDietitianClients();
        if (data && data.length > 0) {
          setClients(data);
        } else {
          // Fallback to mock data if no clients in DB yet (for demo purposes)
          setClients(CLIENTS);
        }
      } catch (err) {
        console.error("Failed to fetch clients, using fallback:", err);
        setClients(CLIENTS);
      } finally {
        setLoading(false);
      }
    };
    loadClients();
  }, []);

  // Filter and split clients
  const filteredClients = clients.filter(client => 
    client.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeClients = filteredClients.filter(c => c.status === 'Aktif');
  const passiveClients = filteredClients.filter(c => c.status === 'Pasif');

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen md:h-screen flex flex-col">
