import React, { createContext, useContext, useEffect, useState } from 'react';
import { Session, User } from '@supabase/supabase-js';
import { supabase } from '../lib/supabaseClient';

interface AuthContextType {
  session: Session | null;
  user: User | null;
  loading: boolean;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType>({
  session: null,
  user: null,
  loading: true,
  signOut: async () => {},
});

export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
  const [session, setSession] = useState<Session | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check active session
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    // Listen for changes
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const signOut = async () => {
    await supabase.auth.signOut();
  };

  return (
    <AuthContext.Provider value={{ session, user, loading, signOut }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

import { supabase } from '../lib/supabaseClient';
import { Client } from '../types';
import { USER_AVATAR } from '../constants';

/**
 * Fetches clients associated with the logged-in dietitian.
 * Assumes 'clients' table has a 'dietitian_id' column or RLS policies in place.
 */
export const fetchDietitianClients = async (): Promise<Client[]> => {
  const { data, error } = await supabase
    .from('clients')
    .select('*');

  if (error) {
    console.error('Error fetching clients:', error);
    throw error;
  }

  // Map Supabase DB shape to App UI shape
  // This handles missing fields by providing defaults to prevent UI crashes
  return (data || []).map((dbClient: any) => ({
    id: dbClient.id,
    name: dbClient.name || dbClient.full_name || 'İsimsiz Danışan',
    email: dbClient.email || '',
    avatar: dbClient.avatar_url || USER_AVATAR, // Fallback to generic if no avatar
    status: dbClient.status === 'active' ? 'Aktif' : 'Pasif',
    goal: dbClient.goal || 'Sağlıklı Yaşam',
    startDate: dbClient.start_date ? new Date(dbClient.start_date).toLocaleDateString('tr-TR') : '-',
    duration: dbClient.duration || '1 Ay',
    currentWeight: dbClient.current_weight ? `${dbClient.current_weight} kg` : '-',
    weeklyChange: dbClient.weekly_change || 0,
    compliance: dbClient.compliance_score || 0,
  }));
};

/**
 * Fetch meal plans for a specific client
 */
export const fetchClientMealPlans = async (clientId: string) => {
  const { data, error } = await supabase
    .from('meal_plans')
    .select('*')
    .eq('client_id', clientId);

  if (error) {
    console.error('Error fetching meal plans:', error);
    throw error;
  }
  return data;
};

/**
 * Fetch current Dietitian profile
 */
export const fetchDietitianProfile = async () => {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return null;

  // Assuming a 'dietitians' or 'profiles' table exists
  const { data, error } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .single();

  if (error) return null;
  return data;
};

